CREATE TABLE IF NOT EXISTS optical_prescriptions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, party_id uuid NOT NULL REFERENCES parties(id), invoice_line_id uuid REFERENCES sales_invoice_lines(id) ON DELETE SET NULL, orientation text NOT NULL DEFAULT 'distance', right_eye jsonb NOT NULL DEFAULT '{}', left_eye jsonb NOT NULL DEFAULT '{}', other_grid jsonb NOT NULL DEFAULT '{}', notes text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE INDEX IF NOT EXISTS optical_prescriptions_party_idx ON optical_prescriptions(tenant_id, party_id);
CREATE INDEX IF NOT EXISTS optical_prescriptions_line_idx ON optical_prescriptions(tenant_id, invoice_line_id);
CREATE TABLE IF NOT EXISTS customer_measurements (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, party_id uuid NOT NULL REFERENCES parties(id), kind text NOT NULL DEFAULT 'tailoring', measurements jsonb NOT NULL DEFAULT '{}', notes text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE INDEX IF NOT EXISTS customer_measurements_party_idx ON customer_measurements(tenant_id, party_id, created_at);
CREATE TABLE IF NOT EXISTS vessel_groups (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, name text NOT NULL, code text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS vessel_groups_code_key ON vessel_groups(tenant_id, code) WHERE code IS NOT NULL AND deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS vessels (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, group_id uuid REFERENCES vessel_groups(id) ON DELETE SET NULL, code text NOT NULL, name text NOT NULL, status text NOT NULL DEFAULT 'available', capacity int NOT NULL DEFAULT 0, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS vessels_code_key ON vessels(tenant_id, code) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS vessels_group_idx ON vessels(tenant_id, group_id);
CREATE TABLE IF NOT EXISTS vessel_group_pricing (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, group_id uuid NOT NULL REFERENCES vessel_groups(id) ON DELETE CASCADE, period_kind text NOT NULL CHECK (period_kind IN ('hour','half_hour','offer','day')), price numeric(20,4) NOT NULL, currency text NOT NULL DEFAULT 'SAR', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS vessel_group_pricing_kind_key ON vessel_group_pricing(tenant_id, group_id, period_kind);
CREATE TABLE IF NOT EXISTS vessel_owners (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, vessel_id uuid NOT NULL REFERENCES vessels(id) ON DELETE CASCADE, party_id uuid NOT NULL REFERENCES parties(id), percent numeric(7,4) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid);
CREATE UNIQUE INDEX IF NOT EXISTS vessel_owners_party_key ON vessel_owners(tenant_id, vessel_id, party_id) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS marina_bookings (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, branch_id uuid NOT NULL REFERENCES branches(id), party_id uuid NOT NULL REFERENCES parties(id), vessel_id uuid NOT NULL REFERENCES vessels(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, companions int NOT NULL DEFAULT 0, insurance_amount numeric(20,4) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'booked', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE INDEX IF NOT EXISTS marina_bookings_vessel_time_idx ON marina_bookings(tenant_id, vessel_id, starts_at, ends_at);
CREATE TABLE IF NOT EXISTS marina_booking_additions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, booking_id uuid NOT NULL REFERENCES marina_bookings(id) ON DELETE CASCADE, description text NOT NULL, amount numeric(20,4) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS rental_invoices (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, booking_id uuid NOT NULL REFERENCES marina_bookings(id), sales_invoice_id uuid REFERENCES sales_invoices(id) ON DELETE SET NULL, period_amount numeric(20,4) NOT NULL, additions_amount numeric(20,4) NOT NULL DEFAULT 0, insurance_amount numeric(20,4) NOT NULL DEFAULT 0, total numeric(20,4) NOT NULL, status text NOT NULL DEFAULT 'draft', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS rental_invoices_booking_key ON rental_invoices(tenant_id, booking_id);
CREATE TABLE IF NOT EXISTS marina_violations (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, vessel_id uuid REFERENCES vessels(id), booking_id uuid REFERENCES marina_bookings(id), party_id uuid REFERENCES parties(id), violation_date date NOT NULL, amount numeric(20,4) NOT NULL DEFAULT 0, description text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE TABLE IF NOT EXISTS marina_operation_plans (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, group_id uuid REFERENCES vessel_groups(id), plan_date date NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE INDEX IF NOT EXISTS marina_operation_plans_day_idx ON marina_operation_plans(tenant_id, plan_date);
CREATE TABLE IF NOT EXISTS marina_operation_plan_lines (plan_id uuid NOT NULL REFERENCES marina_operation_plans(id) ON DELETE CASCADE, line_no int NOT NULL, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, vessel_id uuid NOT NULL REFERENCES vessels(id), period_label text, metadata jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(plan_id, line_no));
CREATE TABLE IF NOT EXISTS vehicle_makes (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS vehicle_makes_name_key ON vehicle_makes(tenant_id, name) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS vehicle_models (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, make_id uuid NOT NULL REFERENCES vehicle_makes(id) ON DELETE CASCADE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS vehicle_models_name_key ON vehicle_models(tenant_id, make_id, name) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS item_vehicle_fitment (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES items(id) ON DELETE CASCADE, make_id uuid NOT NULL REFERENCES vehicle_makes(id), model_id uuid REFERENCES vehicle_models(id), year_from int, year_to int, notes text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE INDEX IF NOT EXISTS item_vehicle_fitment_lookup_idx ON item_vehicle_fitment(tenant_id, make_id, model_id, year_from, year_to);
CREATE INDEX IF NOT EXISTS item_vehicle_fitment_item_idx ON item_vehicle_fitment(tenant_id, item_id);
CREATE TABLE IF NOT EXISTS salla_connections (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, store_id text NOT NULL, access_token_enc text NOT NULL, refresh_token_enc text, webhook_secret_enc text NOT NULL, status text NOT NULL DEFAULT 'active', scopes jsonb NOT NULL DEFAULT '[]', expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid);
CREATE UNIQUE INDEX IF NOT EXISTS salla_connections_store_key ON salla_connections(tenant_id, store_id) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS salla_item_sync (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, connection_id uuid REFERENCES salla_connections(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES items(id) ON DELETE CASCADE, remote_id text, last_exported_snapshot jsonb NOT NULL DEFAULT '{}', diff_flags jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'pending', next_retry_at timestamptz, attempts int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS salla_item_sync_item_key ON salla_item_sync(tenant_id, connection_id, item_id);
CREATE TABLE IF NOT EXISTS salla_export_log (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, connection_id uuid REFERENCES salla_connections(id) ON DELETE SET NULL, item_id uuid REFERENCES items(id) ON DELETE SET NULL, action text NOT NULL, status text NOT NULL DEFAULT 'queued', request_payload jsonb NOT NULL DEFAULT '{}', response_payload jsonb, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS salla_export_log_status_idx ON salla_export_log(tenant_id, status);
CREATE TABLE IF NOT EXISTS salla_branch_mappings (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, connection_id uuid REFERENCES salla_connections(id) ON DELETE CASCADE, branch_id uuid REFERENCES branches(id), warehouse_id uuid REFERENCES warehouses(id), cash_location_id uuid, remote_branch_id text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid);
CREATE UNIQUE INDEX IF NOT EXISTS salla_branch_mappings_remote_key ON salla_branch_mappings(tenant_id, connection_id, remote_branch_id) WHERE deleted_at IS NULL;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['optical_prescriptions','customer_measurements','vessel_groups','vessels','vessel_group_pricing','vessel_owners','marina_bookings','marina_booking_additions','rental_invoices','marina_violations','marina_operation_plans','marina_operation_plan_lines','vehicle_makes','vehicle_models','item_vehicle_fitment','salla_connections','salla_item_sync','salla_export_log','salla_branch_mappings'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t); EXECUTE format('DROP POLICY IF EXISTS %I_tenant_isolation ON %I', t, t); EXECUTE format('CREATE POLICY %I_tenant_isolation ON %I USING (tenant_id = current_setting(''app.tenant_id'', true)::uuid) WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true)::uuid)', t, t); END LOOP; END $$;
